'use strict'
import "/allin/lib/adapter/adapter.min.js";
var VideoChat = VideoChat || class {
    constructor() {
        this.peerConnectionConfig = {
            iceServers: [{
                urls: ['stun:xinsj.littlerainbow.cn:3478', 'turn:xinsj.littlerainbow.cn:3478'],
                username: 'xsj',
                credential: 'admin1314'
            }]
        };
        this.Peering =
            class {
                constructor(vChat, user) {
                    this.vChat = vChat;
                    this.user = user;
                    this.peerConnectId = user.connectionId;
                    this.peerConnection;
                    this.remoteVideo;

                }

                addTracksToPeerConnection(stream) {
                    //添加视频流
                    stream.getTracks().forEach(track => {
                        this.peerConnection.addTrack(track, stream);
                    });
                }


            };

        this.avPage = null;

        this.isClosed = false;

        this.topElement = null;

        this.callAudio = null;
        this.recorder = null;

        this.userMedia;
        this.localVideo;

        this.peerings = [];
    }

    /**
     * 为远程用户创建peerconnection,返回offer
     * @param {any} user
     */
    async createPeer(user, buildOffer) {

        console.log("创建Peer:" + user.NickName + ",connId:" + user.connectionId);
        this.removePeerWithUserId(user.userId);
        var curPeer = new this.Peering(this, user);
        this.stopCall();
        var peerConnection = new RTCPeerConnection(this.peerConnectionConfig);

        peerConnection.onicecandidate = function (event) {
            if (!event || !event.candidate) return;
            console.log("触发:ONICE");
            if (this.localDescription) {
                console.log("本地sdp:", this.localDescription.sdp);
            }
            if (this.remoteDescription) {
                console.log("远程sdp:", this.remoteDescription.sdp);
            }
            console.log("candidate:", event.candidate);
            let candidate = new RTCIceCandidate(event.candidate);
            curPeer.user.candidate = JSON.stringify(candidate);
            let strUser = JSON.stringify(curPeer.user);
            curPeer.vChat.avPage.invokeMethodAsync("SendIceCandidate", strUser);
        };
        peerConnection.onicecandidateerror = function (event) {
            console.log("触发:onicecandidateerror，ICE出错", event);
        }
        peerConnection.oniceconnectionstatechange = function () {
            console.log('----------------ICE 状态:------------------ ', peerConnection.iceConnectionState);
        }

        curPeer.peerConnection = peerConnection;
        peerConnection.ontrack = function (event) {

            curPeer.vChat.showmsg("已接通");
            console.log("获取到远程流,peer个数" + curPeer.vChat.peerings.length
            );

            this.remoteVideo = document.getElementById("remoteVideo");
            this.remoteVideo.addEventListener("click", function () {
                this.muted = false;
                this.play();
            });
            var stream = event.streams[0];
            if (this.remoteVideo.srcObject != stream) {
                this.remoteVideo.srcObject = stream;
                console.log("stream", this.remoteVideo.srcObject);
                var audio = this.remoteVideo.srcObject.getAudioTracks();
                console.log("音track个数:", audio.length);



            } else {
                console.log("第二次触发ontrack,两次流相同");
            }

            //audio.muted = false;
            setTimeout(function () {
                var video = document.getElementById("remoteVideo");
                try {
                    video.removeAttribute("muted");
                    video.muted = false;
                    // video.volume = 0.5; 音量

                    video.pause();
                    video.play();

                } catch (e) {
                    console.log("play出错", e);
                }
            }, 1500);


        };

        //     myPeerConnection.oniceconnectionstatechange = handleICEConnectionStateChangeEvent;
        //    myPeerConnection.onicegatheringstatechange = handleICEGatheringStateChangeEvent;
        //    myPeerConnection.onsignalingstatechange = handleSignalingStateChangeEvent;
        //if (user.roomId !== user.userId) { //非房主要发offer

        peerConnection.onnegotiationneeded = async function (ev) {
            //debugger;
            //该事件在把流添加到peerconnection时触发
            console.log("触发：nnegotiationneeded,但不操作", ev);
            //peerConnection.createOffer().then(function (offer) {
            //    return peerConnection.setLocalDescription(offer);
            //})
            //    .then(function () {
            //        curPeer.user.offer = JSON.stringify(offer);
            //        curPeer.avPage.invokeMethodAsync("SendOffer", curPeer.user);
            //    })
            //    .catch(e => console.log(e));


        };
        /*  }*/

        var stream = VideoChat.localStream;
        if (stream) {

            console.log("添加本地流到peer", user);
            const audioTracks = stream.getAudioTracks();
            const videoTracks = stream.getVideoTracks();
            if (audioTracks.length > 0) {
                console.log(`Using audio device: ${audioTracks[0].label}`);
            }
            if (videoTracks.length > 0) {
                console.log(`Using video device: ${videoTracks[0].label}`);
            }
            curPeer.addTracksToPeerConnection(stream);

        }

        this.peerings[user.connectionId] = curPeer;
        if (buildOffer) {

            const offer = await curPeer.peerConnection.createOffer();
            console.log("createPeer设置本地descripton");
            await curPeer.peerConnection.setLocalDescription(offer);
            var strOffer = JSON.stringify(offer);
            user.Offer = strOffer;
            return strOffer;
        } else return "";
    }




    /**
    * 获取回复函
    * @param {any} user
    */
    async getAnswer(user) {
        console.log("为" + user.NickName + "," + user.connectionId + "生成回复");

        let offer = user.offer;
        var curPeer = this.peerings[user.connectionId];
        if (!curPeer) {
            await this.createPeer(user, false);
        }
        curPeer = this.peerings[user.connectionId];

        var bag = JSON.parse(offer);
        if (bag.type == "offer") {
            var remote = new RTCSessionDescription(bag);
            try {
                console.log("getAnswer设置远程description");
                //设置后触发 onice，对ice进行确定选择一个可以连上去的ice
                await curPeer.peerConnection.setRemoteDescription(remote);

            } catch (e) {
                console.log(e);
            }
            const answer = await curPeer.peerConnection.createAnswer();
            console.log("getAnswer设置本地description");
            await curPeer.peerConnection.setLocalDescription(answer);
            this.stopCall();
            return JSON.stringify(answer);

        } else {
            console.log("包类型为空");
        }
        return null;

    }




    /**
     * 保存对方的邀请函
     * @param {any} user
     */
    async setAnswer(user) {

        var curPeer = this.peerings[user.connectionId];
        if (curPeer) {
            var bag = JSON.parse(user.answer);
            if (bag.type == "answer") {
                var sanswer = new RTCSessionDescription(bag);
                try {
                    console.log("setAnswer设置远程,setRemoteDescription");
                    await curPeer.peerConnection.setRemoteDescription(sanswer);

                    console.log("PEERING ACHIEVED");

                } catch (e) {
                    console.log(e);
                }
            }
        }
    }

    /**
     * 添加信道信息，添加后就可以相互通信了
     * @param {any} user
     */

    async addIceCandidate(user) {
        var cand = JSON.parse(user.candidate);

        var iceCandidate = new RTCIceCandidate(cand);
        let curPeer = this.peerings[user.connectionId];
        //console.log(peering);
        //console.log(peering.peerConnection);
        if (curPeer) {
            try {
                console.log("收到远程" + user.NickName + "ICE信息", cand);
                curPeer.peerConnection.addIceCandidate(iceCandidate);
            }
            catch (err) {
                console.log("AddIceCandidate出错,connectId " + connectId, err);
            }
        } else {
            console.log("AddIce", "没有发现 peer", connectId);
        }
    }



    async stopStream(stream) {
        try {
            let tracks = stream.getTracks();
            tracks.forEach(function (track) {
                track.stop();
            });
        } catch (e) {
            console.error(e);
        }

    }



    /**
     * 录音
     * */
    async record() {
        let ac = new AudioContext();
        var mediaStreamDestination = new MediaStreamAudioDestinationNode(ac);
        var local = document.getElementById("localVideo");
        var remote = document.getElementById("remoteVideo");

        let lsource = ac.createMediaStreamSource(local.srcObject);
        let data = [];
        lsource.connect(mediaStreamDestination);
        let rsource = ac.createMediaStreamSource(remote.srcObject);
        rsource.connect(mediaStreamDestination);
        var mixStream = mediaStreamDestination.stream;
        var chat = this;
        if (!this.recorder) {
            let options = { mimeType: 'audio/webm' }
            this.recorder = new MediaRecorder(mixStream, options);
            this.recorder.ondataavailable = function (e) {
                console.log("录到数据:", e.data.size);
                data.push(e.data);
            }
       
            this.recorder.stop = function (e) {
                //处理数据,合并
                lsource.disconnect();
                rsource.disconnect();
                var blob = new Blob(data, { 'type': 'audio/ogg; codecs=opus' });
                console.log("blob length", data.length);
                var audioURL = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = window.URL.createObjectURL(blob);
                link.download = chat.room.curUser.nickName + "mix.webm";
                link.click();
                //window.URL.revokeObjectURL(link.href);
            }
        }

        this.recorder.start(100);
    }

    /**
     * 停止录音
     * */
    async stopRecord() {
        if (this.recorder) {
            this.recorder.stop();
        }
    }


    removePeerWithUserId(userId) {

        for (var i = 0; i < this.peerings.length; i++) {
            var peering = this.peerings[i];
            if (peering.user.userId == userId) {
                if (VideoChat.localStream) {

                    try {
                        VideoChat.localStream.getTracks().forEach(track => {
                            if (this.peerConnection) {
                                this.peerConnection.removeTrack(track);
                            }
                        });

                    } catch (e) {
                        console.error(e);
                    }
                }

                this.peerings.splice(i, 1);
                i--;
            }
        }
    }



    //尝试呼叫
    async tryCall() {
        if (!this.callAudio) {
            this.callAudio = allin.base.playAudio("/allin/audio/call.wav", true);
        }
    }

    //停止呼叫声
    async stopCall() {
        try {
            if (this.callAudio) {
                this.callAudio.loop = false;
                this.callAudio.stoped = true;
                if (this.callAudio.parentNode) {
                    this.callAudio.parentNode.removeChild(this.callAudio);
                }
                this.callAudio = null;
            }
        } catch (e) {
            console.error(e);
        }

    }

    //显示交接信息
    async showmsg(msg) {
        if (!this.topElement) {
            this.topElement = document.getElementById("avChat");
        }
        if (this.topElement) {
            let txtMessage = this.topElement.querySelector(".txtMsg");
            if (txtMessage) {
                txtMessage.innerHTML = msg;
            }
        }
    }


    async start(avPage, room) {
        this.avPage = avPage;
        this.room = room;//chatInfo结构为 {Roomer:"",CurUser,RoomKey,Mode}

        //是否请求视频通话
        this.reqVideo = (this.room.mode == "3" || this.room.mode == "1");
        this.tryCall();

        let vOptions;
        if (this.reqVideo) {
            vOptions = { facingMode: 'user' };
        } else {
            vOptions = false;
        }
        //关闭原来的流
        if (VideoChat.localStream) {
            this.stopStream(VideoChat.localStream);
            VideoChat.localStream = null;
        }


        const constraints = {
            video: vOptions, audio: true
        };

        if (this.recorder) {
            try {

                this.recorder.stop();
            } catch(e) {
            }
            this.recorder = null;
        }
        //const constraints = {
        //    video: vOptions, audio:false
        //};
        var a = navigator.mediaDevices.getSupportedConstraints();
        console.log("媒体支持", a);
        navigator.mediaDevices.getUserMedia(constraints).then((stream) => {

            console.log("stream", stream);
            var audio = stream.getAudioTracks();
            console.log("音track个数:", audio.length);
            console.log("已获取到本地流");
            //注意这里要用静态变量保存流
            VideoChat.localStream = stream;
            VideoChat.localVideo = document.getElementById('localVideo');
            VideoChat.localVideo.srcObject = stream;
            VideoChat.localVideo.play();
            //通知我已经准备好
            this.avPage.invokeMethodAsync("StreamLoaded");
            // this.videoChat.peerings
            // videoChat.startPeerings();

        }).catch((err) => {
            //通知我已经准备好
            this.avPage.invokeMethodAsync("StreamLoaded");

            // if (!videoChat.peering) videoChat.startPeerings();
            console.log(err);
        });

    }

    //关闭
    async close() {

        this.isClosed = true;
        console.log("关闭流");
        //关闭原来的流
        if (VideoChat.localStream) {
            this.stopStream(VideoChat.localStream);
        }

        VideoChat.localStream = null;

        try {

            this.stopCall();
        } catch (e) {
            console.log(e);
        }

        for (var i = 0; i < this.peerings.length; i++) {
            try {
                let peer = this.peerings[i];
                if (peer) this.removePeerWithUserId(peer.UserId);
                peer.peerConnection.close();
                peer.peerConnection.dispose();
            } catch (e) {
                console.log(e);

            }
        }
        this.peerings = [];
    }
};

var videoChat = new VideoChat();

export { videoChat };





